  "standards": [
    {
      "name": "You own everything",
      "icon": "KeyRound",
      "body": "Code in your repository, infrastructure in your cloud account, domains in your registrar. We work inside your organisation rather than handing it over at the end, so nothing you run depends on us still being here."
    },
    {
      "name": "Reviewed before it ships",
      "icon": "GitPullRequest",
      "body": "Every change goes through pull-request review by a second engineer. Tests, linting, dependency scanning and secret scanning run in CI on every commit, and a red pipeline blocks the merge."
    },
    {
      "name": "Secure by default",
      "icon": "ShieldCheck",
      "body": "Least-privilege access, secrets in a managed vault, encryption in transit and at rest, and an architecture review before anything handling personal or payment data goes near production."
    },
    {
      "name": "Documented as we go",
      "icon": "FileText",
      "body": "Architecture decision records, a runbook for the things that break at 3am, and a README a developer who has never met us can follow. Documentation is written during the build, not promised for afterwards."
    },
    {
      "name": "Measured against the goal",
      "icon": "Gauge",
      "body": "We agree in discovery what success is in numbers — conversion, cycle time, hours saved, error rate — and instrument it before launch, so the claim can be checked afterwards rather than argued about."
    },
    {
      "name": "Boring deployments",
      "icon": "Rocket",
      "body": "Environments defined in code, an automated pipeline to staging and production, and a rollback that has been rehearsed. A release should be a non-event, and nothing goes live on a Friday afternoon."
    }
  ],
  "process": [
    {
      "step": "01",
      "name": "Discovery",
      "duration": "3–5 days",
      "body": "A short, paid engagement where we map the problem, the systems it touches and the people who depend on it. You leave with a written scope, a fixed price and an hour estimate — whether or not you continue with us."
    },
    {
      "step": "02",
      "name": "Architecture",
      "duration": "1–2 weeks",
      "body": "Data model, integrations, hosting and the sequence of work. We agree what is in phase one and what is explicitly not, because an unbounded phase one is the most common way a project goes wrong."
    },
    {
      "step": "03",
      "name": "Build",
      "duration": "2–12 weeks",
      "body": "Two-week cycles, each ending in something you can click on a staging URL. Progress is measured in working software, not in percentage-complete on a slide."
    },
    {
      "step": "04",
      "name": "Launch",
      "duration": "3–7 days",
      "body": "Rehearsed migration, a rollback plan written before we need it, and someone from the build team on hand for the first days. Nothing goes live on a Friday afternoon."
    },
    {
      "step": "05",
      "name": "Care",
      "duration": "Ongoing",
      "body": "Monitoring, patches and a monthly allocation of hours for change. The people who answer are the people who built it, which is the whole point of keeping the team small."
    }
  ],
